      "ballot_id": "B006",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum spin Hall effect and topological insulators revealed a robust new organization of electronic states, with broad influence on condensed-matter physics.",
        "attribution": "Kane and Mele provided the foundational theory; Molenkamp's experiments established the quantum spin Hall effect. These roles form a clear theory-experiment attribution.",
        "maturity": "The topological framework and its experimental manifestations have been extensively studied and confirmed over many years.",
        "uncertainties": [
          "The breadth of later topological-insulator work makes the boundaries of credit difficult to define."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory made a major class of strongly correlated electron problems quantitatively tractable and reshaped the theory of materials.",
        "attribution": "Georges, Vollhardt, and Kotliar are central architects of the method and its development, though its broader intellectual foundations and later extensions involve many researchers.",
        "maturity": "The method has been established for decades, tested against experiments, and incorporated into widely used approaches to correlated materials.",
        "uncertainties": [
          "Its impact is primarily methodological, so the prize case depends on judging a theoretical framework as a distinct discovery."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B028",
      "proposed_laureates": [
        "Harald Rose",
        "Knut Urban",
        "Maximilian Haider"
      ],
      "assessment": {
        "nobel_worthiness": "Correcting spherical aberration transformed electron microscopy, enabling substantially sharper imaging and new access to the structure of materials.",
        "attribution": "Rose supplied the key optical ideas, while Haider and Urban were central to implementing and establishing corrected microscopes. The theory and experimental realization are complementary contributions.",
        "maturity": "The instruments have been used broadly for many years, and their performance and scientific value are well confirmed.",
        "uncertainties": [
          "The history of electron-optical correction includes earlier work and contributors beyond these three."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Allan H. MacDonald",
        "Pablo Jarillo-Herrero",
        "Rafi Bistritzer"
      ],
      "assessment": {
        "nobel_worthiness": "Magic-angle twisted bilayer graphene opened a new route to flat-band physics and strongly correlated states in a tunable material.",
        "attribution": "Bistritzer and MacDonald predicted the key moiré band structure; Jarillo-Herrero's group discovered the correlated phases experimentally. The credited roles are distinct and compelling.",
        "maturity": "The flat bands and correlated insulating states have been reproduced and studied widely, while the superconductivity and its relation to other phases remain active research topics.",
        "uncertainties": [
          "The long-term significance of the superconducting state and the full scope of the discovery are not yet settled."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B018",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed how quantum information can be protected despite decoherence, a conceptual step essential to scalable quantum computing.",
        "attribution": "Shor and Steane developed foundational codes, and Kitaev made key contributions to fault-tolerant and topological approaches. The field is broader than any three-person attribution.",
        "maturity": "The principles have been experimentally tested in multiple platforms, though large-scale fault-tolerant operation remains a work in progress.",
        "uncertainties": [
          "The most consequential implementations and the eventual practical reach of error correction are still developing."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B029",
      "proposed_laureates": [
        "Bart J. van Wees",
        "David A. Wharam",
        "Michael Pepper"
      ],
      "assessment": {
        "nobel_worthiness": "Quantized conductance in ballistic semiconductor constrictions exposed fundamental transport behavior in mesoscopic systems and helped establish a new regime of solid-state physics.",
        "attribution": "Van Wees and Wharam independently reported the effect, with Pepper central to the experimental program. Parallel discovery makes a shared award defensible.",
        "maturity": "The conductance quantization is robust, well understood, and confirmed across many devices and experiments.",
        "uncertainties": [
          "The independent, near-contemporaneous discoveries make the precise allocation of experimental credit delicate."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B051",
      "proposed_laureates": [
        "Jagadeesh S. Moodera",
        "Stuart S. P. Parkin",
        "Terunobu Miyazaki"
      ],
      "assessment": {
        "nobel_worthiness": "Room-temperature tunnel magnetoresistance with MgO barriers enabled large spin-dependent signals and helped establish practical magnetic tunnel junctions.",
        "attribution": "Moodera, Parkin, and Miyazaki are associated with pivotal demonstrations and development, but the technology emerged through substantial parallel work across the spintronics community.",
        "maturity": "The effect is reproducible, well characterized, and central to mature magnetic storage and sensing technologies.",
        "uncertainties": [
          "The discovery and engineering contributions are distributed among multiple groups, complicating a narrow attribution."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B030",
      "proposed_laureates": [
        "Pablo Jarillo-Herrero",
        "Xiang Zhang",
        "Xiaodong Xu"
      ],
      "assessment": {
        "nobel_worthiness": "Establishing intrinsic magnetism in atomically thin van der Waals crystals opened a significant new area linking magnetism with two-dimensional materials.",
        "attribution": "The credited researchers led influential demonstrations and development of the field, but independent reports and the diversity of materials make the boundaries of credit uncertain.",
        "maturity": "Intrinsic magnetic order in thin crystals is experimentally established, while material diversity, control, and device-level significance continue to develop.",
        "uncertainties": [
          "The field is relatively young, and its lasting impact beyond the initial material discoveries remains to be demonstrated."
        ]
      }
    }
  ]
